Let $\phi \in$ Hom$(G,$ Aut$_k(K))$ be any action of a group $G$ on a commutative ring $K$ fixing a subring $k\subset K$ elementwise,
and and let $C(K)$ be any set of isomorphism types of $K$-central algebras that contains $[K]$ itself and is closed under $K$-tensoring.
Then there exists an exact sequence of monoids
\begin{eqnarray}\label{main}
\begin{array}{rl}
1&\to H^1(G,K^*_{\phi})\xrightarrow{}{\text{Ext}{(\phi,\text{Pic}(K))}}\xrightarrow{}\text{Pic}(K)^{\phi}\xrightarrow{} H^2(G,K^*_{\phi})\\
&\xrightarrow{}{\raisebox{.1em}{${\tilde{\text{Cliff}}(\phi)}$}\left/\raisebox{-.1em}{${{\mathcal{MC}_K'}(1)}$}\right.}\xrightarrow{} {\raisebox{.1em}{${\mathcal{\tilde{C}}{(\phi)}}$}\left/\raisebox{-.1em}{${{\mathcal{MC}_K'}(1)}$}\right.}

 \xrightarrow{} H^3(G,K^*_{\phi})
\end{array}
\end{eqnarray}
holding, for all $K$-central algebras $R$ whose isomorphism types lie in $C(K)$
\begin{enumerate}
\item the graded Morita classes \eqref{quotcliff} of all strongly $G$-graded $k$-algebras of type $\phi$ over base algebra $R$, as well as
\item the Morita classes \eqref{quotck} of all general collective characters $G\to$Pic$(R)$ of type $\phi$.
\end{enumerate}

\cite[IV; 2.6, 2.7, 2.8]{FDEI}
With the above notation
\begin{enumerate}
\item The map $B^*_P:\begin{array}{ccc}
G\times G&\to & K^*\\
(g,h)&\mapsto & B^*_P(g,h)
\end{array}$ is a 2-cocycle.
\item If $\tilde{B}_P$ is another set of $K$-module isomorphisms
then $$[B^*_P]=[{\tilde{B}^*_P}]\in H^2(G,K^*_{\phi}).$$

\item The well-defined map
\begin{eqnarray}\label{alpha3}\alpha_3 :\begin{array}{ccc}
\text{Pic}(K)^{\phi} &\rightarrow & H^2(G,K^*_{\phi})\\
~[P]&\mapsto & [B^*_P]
\end{array}\end{eqnarray} is a group homomorphism.
\end{enumerate}

\label{Hphiz}
With the above notation there is a group isomorphism
\begin{eqnarray}\label{lambg}
\lambda_{\phi_0}:\begin{array}{ccc}
{\text{Hom}}_{\phi_0}(G,A\rtimes \Gamma)&\xrightarrow{\cong} &Z^1(G,A_{\phi_0})\\
\varphi&\mapsto&\varphi\phi_0^{-1}
