\label{Galdef}
A commutative ring extension $k\subseteq K$ is a Galois extension with Galois group $G=$Aut$_k(K)$ if
\begin{enumerate}
\item $K^G=k$, and
\item for each maximal ideal $M\subseteq K$
and for every nontrivial $g\in G$ there exists $x\in K$ with $x-g(x)\notin M$.
\end{enumerate}

\label{L:2.2}
Let $\phi  \in$ Hom$(G, {\text{Aut}}_k(K))$ be a Galois action. Then the orthogonal idempotents $\{\epsilon_g\}_{g\in G}\subset K \otimes_k K$ satisfy
\begin{equation}\label{theorth}
\epsilon_g(x \otimes_k 1) = \epsilon_g(1 \otimes_k \phi(g)(x)),\ \ \forall g \in G, x \in K.
\end{equation}
In particular,
\begin{equation}\label{eq:OI}
\epsilon_g(K\otimes_k K) = \epsilon_{g}(K \otimes_k 1) = \epsilon_{g}(1 \otimes_k K),\ \ \forall g \in G.
\end{equation}
Moreover, if an idempotent $\epsilon_g' \in K \otimes_k K$ satisfies
$\epsilon_g'(x \otimes_k 1) = \epsilon_g'(1 \otimes_k \phi(g)(x))$ for some $g \in G$ and for every $x\in K$,
then there exists an idempotent $a_g\in K$ such that $\epsilon_g' =\epsilon_g(a_g \otimes_k 1)$.

\label{End_1}
Let $\mathcal{G}$ be a strict monoidal groupoid, then
\begin{enumerate}\item $\text {Id}_{1_{\text {ob}(\mathcal{G})}}$ is the unit of the monoid $\hom(\mathcal{G}).$
\item ${\text{end}}(1_{\text {ob}(\mathcal{G})})$ is closed under tensoring.

Moreover, the monoidal structure of ${\text{end}}(1_{\text {ob}(\mathcal{G})})$ identifies with its group structure by compositions. In particular, $({\text{end}}(1_{\text {ob}(\mathcal{G})}),\otimes)$ is a group.
\end{enumerate}

\begin{enumerate}
\item This is immediate from the strictness assumption.
 \item The closure under tensoring follows from \eqref{tensoring}. The identification of the two structures is a consequence of \eqref{MonGroup}, Indeed, for every $f,g\in{\text{end}}(1_{\text {ob}(\mathcal{G})})$
$$f\circ g=(f\otimes 1_{\hom}){\circ}( 1_{\hom}\otimes g)= (f\circ 1_{\hom})\otimes(1_{\hom}\circ g)=f\otimes g.$$
 \end{enumerate}

\label{orblemma}
Let a strict monoidal groupoid $\mathcal{G}$ with identity $1_{\text{ob}(\mathcal{G})}$ act on a monoid $(A,\otimes_A)$ with identity $1_A$. Then
\begin{enumerate}
\item The orbit $[1_A]_{\mathcal{G}}$ is a submonoid of $A$.

\item The rule $f\mapsto f(1_A)$ defines a group homomorphism from $\text{end}(1_{\text{ob}(\mathcal{G})})$ onto the subgroup
$\{f(1_A)\mid f\in\text{end}(1_{\text{ob}(\mathcal{G})})\}$ of the monoid $[1_A]_{\mathcal{G}}$.
\item The orbits under this action are endowed with a well-defined monoidal structure
$$[a]_{\mathcal{G}}\otimes_{[A]}[a']_{\mathcal{G}}:=[a\otimes_A a']_{\mathcal{G}},\ \ \forall a,a'\in A.$$
\end{enumerate}

\label{quotmor}
Let $\mathcal{G},\mathcal{G}'$ be strict monoidal groupoids acting on monoids $A,A'$ respectively.
Then a monoid homomorphism $\varphi:A\to A'$ gives rise to a well-defined monoid homorphism
$\bar{\varphi}:\begin{array}{ccc}
A/\mathcal{G}&\to& A'/\mathcal{G}'\\
~[a]_{\mathcal{G}}&\mapsto&[\varphi(a)]_{\mathcal{G}'}
\end{array}$

if and only if for every admissible pair $(f,a)\in \hom(\mathcal{G})\times A$,

there exists $f'\in$hom$(\mathcal{G}')$ with $f'(\varphi(a))=\varphi(f(a))$.
In particular, the quotient map $\begin{array}{ccc}
A&\to& A/\mathcal{G}\\
~a&\mapsto&[a]_{\mathcal{G}}
\end{array}$ is a homomorphism of monoids.

\label{wdPc}
The rule \eqref{M^C} gives rise to a well-defined action of the groupoid $\mathcal{MC}'_K$,
and hence also of the groupoid $\mathcal{MC}'_K(1)$, on $\bigsqcup_{R\in \text {ob}({\mathcal{MC}'_{K})}}$Pic$(R)$.

With the notation \eqref{commrule}, the well-defined map
