Let \eqref{psig} be the collection of bijections determining the 2-cocycle $c_P$ as an image of $\alpha_3$, that is (see \eqref{fP})
\begin{equation}\label{f_P}
c_P(g,h)\star p =  \tilde{\psi}_{gh}\tilde{\psi}_h^{-1}\tilde{\psi}_g^{-1}(p),\ \ \forall g,h \in G, p\in P.
\end{equation}
 Using these bijections and the map $\Delta_P :=\theta_P^{-1}\circ\mu_P:P\otimes_1 \check{P} \xrightarrow{\cong}K$ (see \eqref{Delta_P}), consider the map



\begin{eqnarray}\label{Gamma}\Gamma_P : \begin{array}{ccc}
P(K_{\phi}^{c_P}G) &\rightarrow & K_{\phi}G\\
p \otimes_1 a_gv_g \otimes_1 f &\mapsto &{g}(\Delta_P(\tilde{\psi}_g^{-1}(p) \otimes_1f))a_gu_g,
\end{array}
\end{eqnarray}for $p \in P, f \in \check{P},$ and $a_g \in K.$
Now by the multiplication rule in $K_{\phi}G$, for $p_1,p_2 \in P, f_1 ,f_2 \in \check{P},$ and $a_g,a_h \in K$
\begin{align*}
&\Gamma_P(p_1\otimes_1 a_gv_g \otimes_1 f_1)\cdot\Gamma_P(p_2\otimes_1 a_hv_h \otimes_1 f_2)\\
=&\ {g}(\Delta_P(\tilde{\psi}_g^{-1}(p_1) \otimes_1 f_1))a_gu_g\cdot {h}(\Delta_P(\tilde{\psi}_h^{-1}(p_2) \otimes_1 f_2))a_hu_h\\
=&\ a_g\cdot g(a_h)\cdot {g}(\Delta_P(\tilde{\psi}_g^{-1}(p_1) \otimes_1 f_1))\cdot {gh}(\Delta_P(\tilde{\psi}_h^{-1}(p_2) \otimes_1 f_2))u_{gh}\cdots
\end{align*}


Since $\Delta_P$ is a $K$-bimodule isomorphism and further by \eqref{tildepsi}, we obtain
\begin{align*}
\cdots =&\ a_g\cdot g(a_h)\cdot {gh}(\Delta_P(h^{-1}(\Delta_P(\tilde{\psi}_g^{-1}(p_1) \otimes_1 f_1))\star\tilde{\psi}_h^{-1}(p_2) \otimes_1 f_2))u_{gh}\\
=&\ a_g\cdot g(a_h)\cdot {gh}(\Delta_P(\tilde{\psi}_h^{-1}(\Delta_P(\tilde{\psi}_g^{-1}(p_1) \otimes_1 f_1)\star p_2) \otimes_1 f_2))u_{gh}\cdots
\end{align*}
Now applying \eqref{DeltaTau} and then using \eqref{tildepsi} yields
\begin{align*}
\cdots=&\  a_g\cdot g(a_h)\cdot {gh}(\Delta_P(\tilde{\psi}_h^{-1}(\tilde{\psi}_g^{-1}(p_1) \cdot f_1( p_2)) \otimes_1 f_2))u_{gh}\\
=&\ a_g\cdot g(a_h)\cdot g(f_1( p_2))\cdot {gh}(\Delta_P(\tilde{\psi}_h^{-1}(\tilde{\psi}_g^{-1}(p_1)) \otimes_1 f_2))u_{gh}\cdots
\end{align*}
By \eqref{f_P} and then again by \eqref{tildepsi} we have
\begin{align*}
\cdots=&\  a_g\cdot g(a_h)\cdot g(f_1( p_2))\cdot {gh}(\Delta_P(\tilde{\psi}_{gh}^{-1}(c_P(g,h)\star p_1) \otimes_1 f_2))u_{gh}\\
=&\  a_g\cdot g(a_h)\cdot g(f_1( p_2))\cdot c_P(g,h)\cdot {gh}(\Delta_P(\tilde{\psi}_{gh}^{-1}(p_1) \otimes_1 f_2))u_{gh}\cdots
\end{align*}
Finally, by the definition of $\Gamma_P$ \eqref{Gamma}, and further using the multiplication rule \eqref{mult} in $P(K_{\phi}^{c_P}G)$, we obtain
\begin{align*}
\cdots=&\ \Gamma_P(p_1 \otimes_1 a_g\cdot g(a_h) \cdot g(f_1(p_2)) \cdot c_P(g,h)v_{gh} \otimes_1 f_2)\\
=&\ \Gamma_P((p_1 \otimes_1 a_gv_g \otimes_1 f_1)\cdot(p_2 \otimes_k a_hv_h \otimes_1 f_2)).
\end{align*}
Therefore, \eqref{Gamma} is a $G$-graded homomorphism.
By Lemma \ref{grhom} it is left to show that \eqref{Gamma} respects the embeddings $\iota_1$ and $\iota_2$.
Indeed, by choosing a normalized representative $c_P$ in its cohomology class, one can choose $\tilde{\psi}_e$=Id$_P$ in \eqref{psig}. Then,
for every $x \in K$, by using the definition of $P(\iota_1)$ (see \eqref{A^C}),
we have $$\Gamma_P\circ P(\iota_1)(x)=\Gamma_P(\sum\limits_{j}x\star p_j \otimes_1 u_e \otimes_1 p_j')= \sum\limits_j \Delta_P(x\star p_j\otimes_1 p_j')u_e = xu_e ,$$
and \eqref{cleqcl} holds true.

\label{lambdalem}
Let $\phi \in$ Hom$_k(G,$ Aut$_k(K))$. Then under the isomorphism \eqref{lamb'g}, the subgroup $\text{Pic}(K)(1_{\phi})<{\mathcal{\tilde{C}}{(\phi,K)}}$ is mapped onto the coboundary subgroup
$B^1(G,\text{Pic}(K)_{\phi})$ of $Z^1(G,\text{Pic}(K)_{\phi})$.
Consequently, there is a well-defined isomorphism
\begin{eqnarray}\label{lambarg}
\bar{\lambda}_{\phi}:\begin{array}{ccc}
{\mathcal{\tilde{C}}{(\phi,K)}}/_{\mbox{Pic($K$)}}&\xrightarrow{\cong} &H^1(G,\text{Pic}(K)_{\phi})\\
\text{Pic}(K)(\Phi) &\mapsto&[\Phi\phi^{-1}]
\end{array}.\end{eqnarray}

An element in the orbit $\text{Pic}(K)([1_{\phi}]_{})$ of $[1_{\phi}]_{}$ under the $\text{Pic}(K)$-action is of the form (see \eqref{M^C} and \eqref{GCC^C})
\begin{equation}\label{P1phi}
[P](1_{\phi})=[P \otimes_{K} \ K_{1,\phi} \otimes_K \check{P}]
\end{equation}
for some $[P]\in\text{Pic}(K).$

On the other hand, a map $G\to\text{Pic}(K)$ is a 1-coboundary if and only if there exists $[P]\in\text{Pic}(K)$ such that
\begin{equation}\label{cobou}
g\mapsto[P]\otimes_Kg([P]^{-1})=[P \otimes_K \ K_{1,\phi(g)} \otimes_K \check{P} \otimes_K \ K_{1,\phi(g^{-1})}]
\end{equation}
for every $g\in G$.
The fact that \eqref{P1phi} and \eqref{cobou} correspond under \eqref{lamb'g} settles the first part of the claim, which together with \eqref{Ckmod}
prove the isomorphism \eqref{lambarg}.

