\label{L:2.1}
Let $\phi \in$ Hom$(G, {\text{Aut}}_k(K))$ be a Galois action, and let $[P] \in \text{Pic}(K)$. Then with the $G$-grading \eqref{kanzgr}, the homomorphism
\eqref{mu} yields a graded $k$-isomorphism $P(K_{\phi}G) \stackrel{G}{\cong} $ End$_k(P)$.

It is not hard to verify that \eqref{mu} respects the $G$-grading.
We show that the $k$-algebra homomorphism \eqref{mu} has an inverse.
With the notation \eqref{mjf'j}, let
\begin{eqnarray}\label{mu'}
~\ \mu'' :\begin{array}{rcl}
{\text{end}}_k(P)& \rightarrow &P(K_{\phi}G)\\
\varphi_g &\mapsto &\sum\limits_j \varphi_g(p_j') \otimes_K u_g \otimes_K f_j'
\end{array},\ \ \forall\varphi_g \in ({\text{end}}_k(P))_g.\end{eqnarray}

Then for every $p\in P$ and $f\in \check{P}$ we have
\begin{align*}
\mu''\circ\mu'(p\otimes_K u_g \otimes_K f) =&\  \sum\limits_j \mu'(p\otimes_K u_g \otimes_K f){(p'_j)} \otimes_K u_g \otimes_K f_j'=\cdots
\end{align*}
 by the definition of $\mu'$ in \eqref{mu} we have
\begin{align*}
\cdots=\ \sum\limits_j\ {\phi(g)}(f(p'_j))\star p\otimes_K u_g \otimes_K f_j'= \sum\limits_j p \otimes_K  {\phi(g)}(f(p'_j))u_g \otimes_K f_j'\\
= p \otimes_K u_g \otimes_K \sum\limits_jf(p'_j)f_j'
= p\otimes_K u_g \otimes_K f,
\end{align*}
where the last equality follows from \eqref{fm_jf_j'}. Then \eqref{mu'} is a left inverse of \eqref{mu}.
Conversely, let $\varphi_g \in ({\text{end}}_k(P))_g$. Applying the definitions \eqref{mu} and \eqref{mu'} on any $p \in P$ yields
\begin{align*}
\mu'\circ\mu''(\varphi_g):p \mapsto&\ \mu'( \sum\limits_j \varphi_g(p'_j) \otimes_K u_g \otimes_K f_j')(p)= \sum\limits_j{\phi(g)}(f_j'(p))\star\varphi_g(p_j')=\cdots
\end{align*}
Since $\varphi_g \in ({\text{end}}_k(P))_g$ (see \eqref{kanzgr}), we have
\begin{align*}
\cdots= \sum\limits_j \varphi_g(f_j'(p)\star p'_j)=\varphi_g( \sum\limits_j f_j'(p)\star p'_j)=\varphi_g( \sum\limits_j p'_j\cdot f_j'(p))
 = \varphi_g(p),
\end{align*}
where the last equality is \eqref{mjf'j}. Therefore, $\mu'\circ\mu''(\varphi)=\varphi$ for every $\varphi \in {\text{end}}_k(P)$, and so
$\mu'$ is also a right inverse of \eqref{mu}, completing the proof.

\label{L:2.11}
Let $[A_G]\in {\tilde{\text{Cliff}}(\phi,K)}$, where $\phi \in$ Hom$(G, {\text{Aut}}_k(K))$ is a Galois action.
Then $[A_G]\in\text{Pic}(K)([K_{\phi}G])$ if and only if $A_G\stackrel{G}{\cong}{\text{end}}_k(P)$ for some $[P]\in\text{Pic}(K)$.

\label{L:2.9}
Let $\phi \in$ Hom$(G, {\text{Aut}}_k(K))$ be a Galois action. Then with the above notation we have for every $g,h\in G$
\begin{equation}\label{Miyash}
\sum\limits_i(a^g_i \otimes_k 1)\epsilon_h(b^g_i \otimes_k 1)=\epsilon_{hg},\ \ \sum\limits_{i'}(1\otimes_k a'^g_{i'})\epsilon_h(1\otimes_k b'^g_{i'})=\epsilon_{gh},
\end{equation}
and hence for every $g,h\in G,\ c_g\in A_{g^{}}$ and $c'_g\in A'_{g}$
\begin{equation}\label{pass}
(c_g \otimes_k 1)\epsilon_{hg}=\epsilon_{h}(c_g \otimes_k 1),\ \ \epsilon_{gh}(1\otimes_k c'_g)=(1\otimes_k c'_g)\epsilon_{h}.
\end{equation}
In particular, for every $h\in G$, $\epsilon_h$ is full, that is
\begin{equation}\label{prefull}
(A_G \otimes_k A'_G)\epsilon_h (A_G \otimes_k A'_G)=A_G \otimes_k A'_G.
\end{equation}

\label{L:2.5}
Let $\phi \in$ Hom$(G, {\text{Aut}}_k(K))$ be a Galois action. Then with the notations in Lemma \ref{L:2.9},
for every $h\in G$ there is an equality of Brauer classes $[\epsilon_h(A_G\otimes_{k}A'_G)\epsilon_h]_{{\text{Br}}(k)}=[A_G\otimes_{k}A'_G]_{{\text{Br}}(k)}$.

\label{L:2.3}
Let $[A_G],[A'_G]\in {\tilde{\text{Cliff}}(\phi,K)}$

of Galois type $\phi \in$ Hom$(G, {\text{Aut}}_k(K))$. Then with the above notation
\begin{equation}\label{eq:A2}
\epsilon_{}(c_{g_1}\otimes_{k}c'_{g_2})\epsilon_{}=\{
\begin{array}{cc}
\epsilon_{}(c_{g_1}\otimes_{k}c'_{g_2})=(c_{g_1}\otimes_{k}c'_{g_2})\epsilon_{}&\text{ if }g_1= g_2\\
0&\text{ if }g_1\neq g_2
