\end{equation}

\label{L:2.4}With the notation in Lemma \ref{L:2.3},
 the map \begin{eqnarray}\label{eAe}
\theta:\begin{array}{ccc} A_G \otimes_{\phi} A'_G& \rightarrow& \epsilon(A_G \otimes_{k} A'_G)\epsilon\\
a_g \otimes_{\phi(g)} a'_g &\mapsto &\epsilon(a_g \otimes_k a'_g)\epsilon
\end{array} \end{eqnarray}
is an isomorphism of $k$-algebras.

We first show that the map \eqref{eAe} is well-defined, then utilize \eqref{eq:A2} to prove that this map is a homomorphism and finally give an inverse map to deduce that \eqref{eAe}
 is in-fact an isomorphism. To prove that \eqref{eAe} is well-defined, we need to verify that the relation \eqref{scalpass} is preserved by this map.
For $a_g \in A_g, a'_g \in A'_g$ and $x \in K$ we have


$$\theta(a_g\cdot x \otimes_{\phi(g)} a'_g) = \epsilon(a_g\cdot x \otimes_{k} a'_g)\epsilon= \epsilon(a_g\otimes_k 1)(x \otimes_{k} 1)(1 \otimes_{k} a'_g)\epsilon=\cdots$$
By \eqref{pass} and then by \eqref{theorth}
$$\cdots= ( a_g\otimes_{k} 1)\epsilon_g(x\otimes_{k} 1)(1 \otimes_{k} a'_g)\epsilon=( a_g\otimes_{k} 1)\epsilon_g(1\otimes_{k} \phi(g)(x))(1 \otimes_{k} a'_g)\epsilon=\cdots,$$
and back again by \eqref{pass}
\begin{align*}
\cdots=\epsilon( a_g\otimes_{k} 1)(1\otimes_{k} \phi(g)(x) a'_g)\epsilon = \epsilon(a_g\otimes_{k} \phi(g)(x) a'_g)\epsilon= \theta (a_g \otimes_{\phi(g)}\phi(g)(x) a'_g),
\end{align*}

verifying that \eqref{eAe} respects the skew product.

Next, consider $a_g \in A_g, a_h \in A_h, a'_g \in A'_g$ and $a'_h \in A'_h$. Then
$$\theta(a_g \otimes_{\phi(g)} a'_g)\theta(a_h\otimes_{\phi(h)} a'_h)= \epsilon(a_g\otimes_{k} a'_g)\epsilon^2(a_h\otimes_{k} a'_h)\epsilon=\cdots$$
By \eqref{eq:A2}

$$\cdots= \epsilon(a_g\otimes_{k} a'_g)(a_h \otimes_{k} a'_h)\epsilon= \theta((a_g\otimes_{\phi(g)} a'_g)(a_h \otimes_{\phi(h)} a'_h)),$$

and hence \eqref{eAe} is multiplicative.
To end the proof, observe that due to \eqref{eq:A2}, $\epsilon(A_g \otimes_{k} A'_h)\epsilon=0$ for $g\neq h$. Therefore, it is not hard to check that the map
$$\begin{array}{ccc}
\epsilon(A_G \otimes_{k} A'_G)\epsilon &\rightarrow &A_G \otimes_{\phi} A'_G\\
\epsilon(a_g \otimes_{k} a'_g)\epsilon &\mapsto & a_g \otimes_{\phi(g)} a'_g
\end{array},\ \ a_g \in A_g, a'_g \in A'_g$$
serves as an inverse of \eqref{eAe}.

\label{Galcase2}
